import { useEffect, useState } from 'react';
import { JxToggle, JxSlider, JxSwitch, JxDivider, JxSelect, JxBadge } from '@jinx-ui/react';

interface AppearanceSettings {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  font: string;
}

const themeLabels: Record<AppearanceSettings['theme'], string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<AppearanceSettings['theme']>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        maxWidth: 420,
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            fontSize: 20,
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: 14 }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as AppearanceSettings['theme'])}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Sans' },
          { value: 'serif', label: 'Serif' },
          { value: 'mono', label: 'Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

